// Per-school brand theming. Hand-maintained (NOT regenerated by the ingest pipeline).
//
// `color` is each school's accent throughout the UI, keyed to its official athletic
// colors (verified July 2026 against each school's athletics/mascot info). Because
// these six schools share a narrow palette — three lean navy/blue — the blues are
// graded dark→bright so the schools stay visually distinct. The UI derives light/dark
// tints from this one hex automatically, so only the hex needs to change.
//
// `initials` is the badge monogram. New schools that appear in schools.json but are
// missing here fall back to a neutral slate color and auto-generated initials.
//
// `logo` is the school's official athletics mascot mark, shown on the school-page header.
// Files live in `public/logos/<slug>.png` (transparent PNG). Provenance + source URLs
// for each are in `source-material/branding/<slug>/`. These are trademarked marks kept
// for a private research tool; schools without a logo simply show no crest.

// `welcomeVideoUrl` is the school's own introduction video, embedded above the
// research areas on its dossier page. Must be a YouTube **embed** URL
// (`https://www.youtube.com/embed/<id>`), not a watch/share link. Optional —
// schools without one hide the Welcome Video section and its two TOC entries.

export type Brand = {
  color: string
  initials: string
  logo?: string
  welcomeVideoUrl?: string
}

export const BRANDS: Record<string, Brand> = {
  cannon: {
    color: '#8a2433', // Cougars — maroon & gold
    initials: 'CA',
    logo: '/logos/cannon.png',
    welcomeVideoUrl: 'https://www.youtube.com/embed/dI5x4KEkBSY',
  },
  'charlotte-christian': {
    color: '#1e40af', // Knights — royal blue & white
    initials: 'CC',
    logo: '/logos/charlotte-christian.png',
    welcomeVideoUrl: 'https://www.youtube.com/embed/Be0ULPLDrMM',
  },
  'charlotte-country-day': {
    color: '#107a43', // Buccaneers — green & gold
    initials: 'CD',
    logo: '/logos/charlotte-country-day.png',
    welcomeVideoUrl: 'https://www.youtube.com/embed/voNR9UF346g',
  },
  'charlotte-latin': {
    color: '#12294f', // Hawks — navy & white
    initials: 'CL',
    logo: '/logos/charlotte-latin.png',
    welcomeVideoUrl: 'https://www.youtube.com/embed/QvM-MuKndus',
  },
  'covenant-day': {
    // Lions — blue & gold (MaxPreps). #002855 is the site's own CSS
    // `primary-color` custom property (covenantday.org, checked 2026-08-15) —
    // the darkest navy in the set, distinct from Latin's #12294f.
    color: '#002855',
    initials: 'CV', // 'CD' is taken by Charlotte Country Day's badge
  },
  'davidson-day': {
    color: '#1e5fd1', // Patriots — red, white & navy
    initials: 'DD',
    logo: '/logos/davidson-day.png',
    welcomeVideoUrl: 'https://www.youtube.com/embed/wTYvCc7FXCs',
  },
  'providence-day': {
    color: '#be123c', // Chargers — red, white & navy
    initials: 'PD',
    logo: '/logos/providence-day.png',
    welcomeVideoUrl: 'https://www.youtube.com/embed/EfrQPAWsqv8',
  },
}

const FALLBACK_COLOR = '#5b6472'

export function brandFor(slug: string, name: string): Brand {
  const found = BRANDS[slug]
  if (found) return found
  // Derive initials from the display name (e.g. "Queens Grant" -> "QG").
  const initials =
    name
      .replace(/\bSchool\b/gi, '')
      .split(/\s+/)
      .filter(Boolean)
      .slice(0, 2)
      .map((w) => w[0]?.toUpperCase() ?? '')
      .join('') || slug.slice(0, 2).toUpperCase()
  return { color: FALLBACK_COLOR, initials }
}
